SELECT DATE_TRUNC('QUARTER', hire_date) AS quarter_start, CASE WHEN salary >= 148000 THEN 'HIGH' ELSE 'LOW' END AS salary_tier, ROUND(SUM(salary) / NULLIF(COUNT(CASE WHEN job_title = 'Manager' THEN 1 END), 0), 2) AS salary_per_manager, COUNT(CASE WHEN job_title = 'Manager' THEN 1 END) AS manager_count, APPROX_PERCENTILE(salary, 0.95) AS salary_p95, COUNT_IF(job_title = 'Designer') AS designer_events, SUM(CASE WHEN job_title = 'Analyst' THEN salary ELSE 0 END) AS analyst_salary FROM employees GROUP BY GROUPING SETS ((DATE_TRUNC('QUARTER', hire_date), CASE WHEN salary >= 148000 THEN 'HIGH' ELSE 'LOW' END), (DATE_TRUNC('QUARTER', hire_date))) ORDER BY quarter_start;
